INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145267, 'spa', 'Semejanza, imagen', 'Semejanza, parecido o representación, con énfasis en la similitud con un modelo más que en la mera forma física. En la prohibición del Decálogo (Éx 20:4), תְּמוּנָה aparece junto a פֶּסֶל como ''semejanza'' de cualquier cosa en el cielo, la tierra o el mar. La declaración del salmista ''contemplaré tu semejanza'' (Sal 17:15) emplea la palabra para la esperanza de ver el rostro mismo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145271, 'spa', 'Intercambio, sustituto', 'Sentido concreto de intercambio o sustituto: algo dado o recibido en lugar de otra cosa. Es central en la regulación cúltica de Levítico 27:10, 33, donde tanto el animal consagrado como su sustituto quedan santificados. En Rut 4:7 designa el intercambio que sella una transacción legal. Job 20:18 habla de riqueza como ganancia comercial, mientras que Job 28:17 declara que los vasos de oro no igualan a la sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145273, 'spa', 'Recompensa, retribución', 'Sentido abstracto y moralmente cargado de recompensa o retribución: lo que recae sobre una persona como consecuencia de sus decisiones. Job 15:31 advierte que la ''recompensa'' del engañado será vacuidad; la palabra pasa de una sustitución neutra a un juicio divino. El término adquiere así dimensión jurídica y teológica, donde el intercambio se convierte en veredicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145278, 'spa', 'continuamente, siempre', 'Uso adverbial que significa ''continuamente, siempre, perpetuamente,'' expresando duración o regularidad ininterrumpida. Especialmente frecuente en los Salmos (Sal 16:8; 71:14) y los profetas (Is 49:16; 51:13), a menudo combinado con expresiones temporales como ''todo el día.'' Transmite el sentido temporal constante de una acción o estado que no cesa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145279, 'spa', 'la ofrenda continua (tamid)', 'Uso sustantival como término técnico cultual para el holocausto diario/continuo (הַתָּמִיד), prescrito en Nm 28:3-6 como el sacrificio de la mañana y de la tarde. En Dn 8:11-13 y 12:11, la supresión del תָּמִיד se convierte en un marcador escatológico. El artículo señala la sustantivación: se trata de un sustantivo concreto que designa una ofrenda específica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145288, 'spa', 'Sin defecto (sacrificial) — Término técnico cultual para animales de sacrificio ', 'Sin defecto (sacrificial) — Término técnico cultual para animales de sacrificio libres de defecto corporal, requerido a lo largo de toda la legislación sacerdotal (Éx 12:5, Lv 1:3, Nm 28-29, Ez 43:22-25). Este es el sentido cuantitativamente dominante, reflejo de la centralidad de las ofrendas inmaculadas en el culto israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145289, 'spa', 'Íntegro, recto (moral) — Aplicado a personas que caminan con Dios en integridad ', 'Íntegro, recto (moral) — Aplicado a personas que caminan con Dios en integridad de corazón. Noé fue ''justo, perfecto en su generación'' (Gn 6:9); Dios dice a Abraham ''anda delante de mí y sé perfecto'' (Gn 17:1). El plural sustantivado ''los íntegros'' aparece en Proverbios (11:5, 20) y Salmos (119:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145290, 'spa', 'Perfecto, sin falta (divino) — Predicado del camino de Dios (2 S 22', 'Perfecto, sin falta (divino) — Predicado del camino de Dios (2 S 22:31, Sal 18:30), la obra de Dios (Dt 32:4) y la ley de Dios (Sal 19:7). Aquí la palabra alcanza su cima teológica: la actividad y la revelación divinas son completas, no les falta nada, no admiten fallo alguno. La misma palabra que inspecciona un cordero buscando defectos declara ahora que todo el camino de Dios es sin tacha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145291, 'spa', 'Completo, entero, pleno — Aplicado a períodos de tiempo y objetos, no a personas', 'Completo, entero, pleno — Aplicado a períodos de tiempo y objetos, no a personas ni a Dios. Un ''año completo'' (Lv 25:30), ''semanas completas/sabbats'' (Lv 23:15), un ''día entero'' (Jos 10:13) y el Tumim ''completo'' (1 S 14:41, donde la suerte debe estar íntegra). Nada falta, nada está roto, la medida completa está dada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145311, 'spa', 'Objeto sacro oracular', 'Los Tumim, objeto sagrado cultual usado junto con el Urim para la consulta sacerdotal de la voluntad divina. Las cinco ocurrencias lo emparejan con el Urim en el contexto del pectoral del sumo sacerdote (Éx 28:30; Lv 8:8) o de la consulta oracular (Dt 33:8; Esd 2:63; Neh 7:65). Las traducciones transliteran uniformemente en vez de traducir — ''Thummim'' en inglés, ''Tumim'' en español y francés — reflejando su carácter técnico sacral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145312, 'spa', 'Asir, sujetar — tomar o agarrar algo físicamente con la mano, implicando un agar', 'Asir, sujetar — tomar o agarrar algo físicamente con la mano, implicando un agarre firme e intencional. En Gn 48:17, José sujeta la mano de su padre para redirigir la bendición; en Amós 1:5 y 1:8, el participio describe al que «empuña el cetro», imagen de autoridad política ejercida a través de la mano. Cubre tanto la sujeción inicial como el mantenimiento del agarre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145313, 'spa', 'Aferrarse, obtener, retener — mantener un asimiento firme de algo abstracto', 'Aferrarse, obtener, retener — mantener un asimiento firme de algo abstracto: sabiduría, justicia o un camino de vida elegido. Proverbios emplea este sentido repetidamente: quienes se aferran a la sabiduría hallan vida (Pr 3:18), el padre exhorta «retenga tu corazón mis palabras» (Pr 4:4), e incluso una mujer virtuosa «obtiene honra» mediante tal retención tenaz (Pr 11:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145314, 'spa', 'Sostener, sustentar, apoyar — proveer apoyo sustentador o fuerza física a otra p', 'Sostener, sustentar, apoyar — proveer apoyo sustentador o fuerza física a otra persona, usado frecuentemente de Dios sosteniendo al justo. El salmista confiesa: «mi alma se aferra a ti; tu diestra me sostiene» (Sal 63:8), y el uso paralelo en Sal 41:12 muestra a Yahvé sustentando la integridad del fiel. Evoca una dimensión vertical de soporte que lleva peso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145318, 'spa', 'Ser sujetado (Nifal) — Nifal pasivo', 'Ser sujetado (Nifal) — Nifal pasivo: ser atrapado, prendido o retenido por una fuerza externa, particularmente las cuerdas del propio pecado. Proverbios 5:22 advierte que el impío «será prendido en las cuerdas de su pecado», convirtiendo el verbo activo de asir en imagen de trampa donde el pecador se vuelve el objeto sujetado. Esta única ocurrencia en Nifal invierte por completo la agencia del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145331, 'spa', 'Completarse, terminarse (Qal) — El significado intransitivo básico del Qal', 'Completarse, terminarse (Qal) — El significado intransitivo básico del Qal: alcanzar la plenitud, terminarse o llegar a su fin. Se usa para provisiones que se agotan (Gn 47:15, 18), construcciones que se completan (1 R 7:22), períodos de tiempo que expiran (Lv 25:29) y tareas que llegan a su conclusión natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145333, 'spa', 'Consumirse, perecer (Qal) — Una extensión más sombría del Qal', 'Consumirse, perecer (Qal) — Una extensión más sombría del Qal: ser consumido, agotado o perecer. Aquí el ''fin'' es destructivo: personas muriendo en el desierto (Nm 14:35; Dt 2:15-16), una generación consumida (Nm 17:13) o fuerzas agotadas (Lm 3:22). La distinción respecto al sentido 1 radica en que se trata de una destrucción involuntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145343, 'spa', 'Completar, terminar (Hifil causativo) — El Hifil causativo de la plenitud', 'Completar, terminar (Hifil causativo) — El Hifil causativo de la plenitud: llevar algo activamente a su término. Una persona completa una tarea (2 R 22:4, la reparación del templo), cumple una transacción (2 S 20:18) o Dios lleva planes a su realización (Is 33:1). Donde el sentido 1 describe cosas que terminan por sí solas, este sentido involucra un agente deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145345, 'spa', 'Ser íntegro (Qal aspiracional) — Forma imperfectiva de primera persona en Qal (S', 'Ser íntegro (Qal aspiracional) — Forma imperfectiva de primera persona en Qal (Sal 19:13) que expresa el deseo del salmista de ser irreprochable: ''seré íntegro.'' Aunque cercano al ámbito moral del sentido 5, no es reflexivo-demostrativo sino aspiracional: un estado interior de integridad ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145347, 'spa', 'Consumir, destruir (Hifil causativo) — El Hifil destructivo', 'Consumir, destruir (Hifil causativo) — El Hifil destructivo: causar la consumición o destrucción, poner fin completo a algo. Dios consume a las naciones que resisten (Jer 27:8) o purga la impureza de un pueblo (Ez 22:15; 24:10). Este sentido es paralelo al sentido 2 como el sentido 3 lo es al sentido 1, pero en el eje destructivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145350, 'spa', 'Mostrarse íntegro (Hitpael) — El Hitpael reflexivo', 'Mostrarse íntegro (Hitpael) — El Hitpael reflexivo: mostrarse completo, íntegro o perfecto en conducta. Aparece solo en 2 S 22:26 y Sal 18:25, donde describe el trato recíproco de Dios: ''con el íntegro te muestras íntegro.'' La forma reflexiva transforma la plenitud física en integridad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145383, 'spa', 'Timna (topónimo)', 'Ciudad cananea en la Sefela, zona fronteriza entre Judá y Filistea, identificada con Tel Batash en el valle del Sorec. Judá viaja allí para la esquila y se encuentra con Tamar (Gn 38:12-14). Figura en las asignaciones tribales tanto de Judá (Jos 15:10, 57) como de Dan (Jos 19:43), reflejando su ubicación fronteriza disputada. Sansón baja a Timna para tomar esposa filistea, dando inicio a su carrera como libertador de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145389, 'spa', 'Gentilicio de Timna', 'En Jueces 15:6, designa a la esposa de Sansón por su ciudad natal: es «la timnatea». El uso del gentilicio en lugar del nombre personal enfatiza su identidad como forastera de la ciudad fronteriza, atrapada entre Israel y Filistea. Su designación por lugar refleja su trágico papel como catalizadora del conflicto de Sansón con los filisteos, que lleva a su muerte a manos de estos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145390, 'spa', 'Timna (nombre propio)', 'Nombre propio que designa a varios personajes edomitas: (a) la mujer horita, hermana de Lotán (Gn 36:22; 1 Cr 1:39) y concubina de Elifaz, madre de Amalec (Gn 36:12); (b) un jefe edomita (Gn 36:40; 1 Cr 1:51); y (c) una figura enumerada entre los descendientes de Elifaz en 1 Crónicas 1:36, que probablemente refleja una lectura tribal más que individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145393, 'spa', 'Ubicación de sepultura', 'En Jueces 2:9, esta frase preposicional señala el lugar de sepultura de Josué —''en Timnat-heres''— en la serranía de Efraín. La posible conexión del topónimo con el culto solar (חֶרֶס/סֶרַח) ha generado debate, aunque el relato lo presenta simplemente como la heredad personal de Josué. La forma paralela en Josué invierte los elementos, una variante frecuente en la nomenclatura geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145395, 'spa', 'Disolución viscosa', 'En el Salmo 58:8, este término describe la aparente disolución del caracol al dejar su rastro baboso, metáfora de cómo los malvados deben desvanecerse. La imagen es visceral: así como el caracol parece derretirse al arrastrarse dejando un rastro líquido, así los impíos deberían disolverse hasta quedar en nada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145396, 'spa', 'palmera datilera', 'La palmera datilera (Phoenix dactylifera), apreciada por su fruto, sombra y porte majestuoso en todo el mundo bíblico. Se encuentra en el oasis de Elim (Éx 15:27), se prescribe para la Fiesta de los Tabernáculos (Lv 23:40; Neh 8:15) y se asocia con Jericó como «la ciudad de las palmeras» (Dt 34:3; Jue 1:16; 3:13). Sirve como símil del florecimiento del justo (Sal 92:12) y como motivo arquitectónico tallado en los templos de Salomón y Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145404, 'spa', 'Nombre propio hebreo que significa ''palmera datilera'', aplicado a tres mujeres y', 'Nombre propio hebreo que significa ''palmera datilera'', aplicado a tres mujeres y un lugar. La nuera de Judá, Tamar, aseguró la línea ancestral mediante una audaz estratagema de levirato que el propio Judá declaró justa (Gn 38:6-26; Rt 4:12). La hija de David, Tamar, fue violada por Amnón, lo que desencadenó la venganza de Absalón (2 S 13:1-22, 32). La hija de Absalón del mismo nombre es destacada por su belleza (2 S 14:27). Como topónimo, marca el límite sureste de Judá en la distribución ideal de la tierra según Ezequiel (Ez 47:19; 48:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145410, 'spa', 'Ornamento de palmera / palmera tallada — figura de palmera tallada o grabada com', 'Ornamento de palmera / palmera tallada — figura de palmera tallada o grabada como ornamentación arquitectónica en edificios sagrados. En el templo de Salomón, las figuras de palmeras adornaban las paredes interiores, las puertas y los paneles junto con querubines y flores abiertas (1 R 6:29, 32, 35). En el templo visionario de Ezequiel, los ornamentos de palmera aparecen en jambas y paredes alternando con querubines (Ez 40:16, 22, 26; 41:18-26). El término se distingue de תָּמָר (palmera viva), designando específicamente la representación artística. Estos relieves simbolizaban vida floreciente y bendición divina en la iconografía templar del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145416, 'spa', 'Tratamientos cosméticos', 'Designa los elaborados tratamientos cosméticos y aromáticos del protocolo real persa. El contexto enfatiza la purificación ritual combinada con el embellecimiento, no un simple adorno sino una limpieza preparatoria. Los seis meses con aceite de mirra y seis con perfumes (Est 2:12) sugieren propósitos tanto medicinales como estéticos, transformando a las candidatas mediante un proceso integral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145417, 'spa', 'Amargura intensa en duelo', 'Amargura intensa, especialmente en contextos de duelo. Jeremías 6:26 ordena ''hacer duelo de amargura'' como por un hijo único—el dolor más profundo imaginable. Jeremías 31:15 retrata a Raquel ''llorando con llanto amargo'', rechazando consuelo por sus hijos perdidos—dolor tan profundo que no puede ser aliviado. Oseas 12:14 lo usa adverbialmente: Efraín ''provocó amargamente''—acciones que ofendieron profundamente a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145418, 'spa', 'Mojones de orientación', 'En Jeremías 31:21, estas señales o mojones guían el viaje de retorno de los exiliados. Israel recibe el mandato de erigirlos para marcar el camino de vuelta a casa. La imagen evoca la práctica antigua de apilar piedras o levantar postes para indicar rutas por el desierto. Metafóricamente, implica recordar el camino del exilio para posibilitar el regreso, tanto la repatriación física como la restauración espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145419, 'spa', 'Símil del monstruo', 'En Ezequiel 32:2, este símil compara a Faraón con ''el monstruo'' o dragón, criatura del caos que Dios derrotará. La imagen fusiona la iconografía del monstruo del caos con los cocodrilos del Nilo, presentando al rey de Egipto como bestia temible y a la vez criatura condenada a la destrucción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145422, 'spa', 'Chacal de ruinas', 'El chacal aparece consistentemente en pasajes bíblicos como la criatura arquetípica de ruinas y abandono. Las glosas multilingües muestran traductores luchando con esta designación animal—algunos traduciéndolo como ''chacales'' mientras otros preservan la transliteración hebrea, reflejando incertidumbre antigua sobre identificación exacta. La característica definitoria de la criatura es su aullido lúgubre en lugares desolados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145424, 'spa', 'Producto agrícola', 'Producto o fruto agrícola, el rendimiento concreto de la tierra cultivada o de los huertos. Deuteronomio 32:13 y Ezequiel 36:30 lo combinan con ''campo'' (שָׂדַי / הַשָּׂדֶה), mientras que Jueces 9:11 lo aplica al fruto propio de la higuera. Lamentaciones 4:9 emplea la falta de producto como señal de hambruna y asedio: personas ''traspasadas por falta de los frutos del campo''. En español se traduce directamente como ''fruto(s)'' o ''producto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145425, 'spa', 'Lóbulo de la oreja', 'Sustantivo masculino que designa la punta o lóbulo de la oreja, empleado únicamente en la frase constructa tenukh ozen («lóbulo de la oreja de») dentro de la legislación ritual sacerdotal. Sus ocho apariciones se distribuyen en dos ceremonias paralelas: la ordenación sacerdotal (Éx 29:20; Lv 8:23-24), donde se aplica sangre sacrificial sobre el lóbulo de la oreja derecha, el pulgar derecho y el dedo gordo del pie derecho; y la purificación del leproso sanado (Lv 14:14, 17, 25, 28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145426, 'spa', 'Somnolencia, adormecimiento', 'Somnolencia o adormecimiento como escenario de la revelación divina. Job 33:15 describe a Dios abriendo los oídos humanos ''en adormecimientos sobre el lecho'', en paralelo con el sueño profundo (תַּרְדֵּמָה). La forma singular o plural no altera el sentido; designa el estado liminal entre la vigilia y el sueño profundo en el cual ocurren las visiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145427, 'spa', 'La ofrenda mecida ritual (28 apariciones), término técnico de la fuente sacerdot', 'La ofrenda mecida ritual (28 apariciones), término técnico de la fuente sacerdotal para las porciones del sacrificio agitadas ante el SEÑOR. El español ''ofrenda mecida'' y el alemán ''Webeopfer'' (sacrificio mecido) captan la dimensión cinética del rito. Pasajes clave incluyen la ofrenda de consagración (Éx 29:24), el oro del tabernáculo (Éx 35:22) y la notable mecida de los propios levitas como ofrenda viva ante Dios (Nm 8:11, 15, 21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145435, 'spa', 'Sentido no cultual (2 apariciones) que denota agitación agresiva o blandimiento', 'Sentido no cultual (2 apariciones) que denota agitación agresiva o blandimiento. En Is 19:16 describe el aterrador blandimiento de la mano del SEÑOR sobre Egipto, y en Is 30:32 se refiere a batallas libradas con armas blandidas. El español ''agitación'' y la energía cinética de la raíz hebrea muestran continuidad con la mecida ritual — el mismo movimiento vigoroso, ahora aplicado a la guerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145438, 'spa', 'Horno (figurado/símil)', 'Horno (figurado/símil). Uso figurado o comparativo que evoca un calor intenso y consumidor como imagen de la ira divina, el juicio o la pasión ardiente. Malaquías 4:1 advierte que el día venidero arderá ''como un horno'', consumiendo a los arrogantes. Oseas compara dos veces a los conspiradores de Israel con un horno calentado por el panadero: su furia arde latente durante la noche y estalla al amanecer (Os 7:4, 6-7). El salmista declara que Dios hará de sus enemigos ''como un horno de fuego'' (Sal 21:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145439, 'spa', 'Horno, hornaza (literal)', 'Horno, hornaza (literal). Horno o fogón físico utilizado para cocer pan y cocinar alimentos, un gran recipiente de barro aún conocido en el Levante. Levítico prescribe ofrendas cocidas ''en el horno'' (Lv 2:4; 7:9) y ordena que los hornos contaminados por animales impuros sean destruidos (Lv 11:35). La plaga egipcia de ranas invadió hornos y artesas por igual (Éx 8:3). En Nehemías, la ''Torre de los Hornos'' (Neh 3:11; 12:38) era un punto de referencia conocido en la muralla de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145448, 'spa', 'Consolación, consuelo', 'Consolación o consuelo, siempre en plural, que denota palabras, actos o garantías divinas que alivian el dolor. Jeremías 16:7 lo enraíza en el ritual de duelo; Job 15:11 y 21:2 debaten si los argumentos teológicos constituyen genuina consolación. El Salmo 94:19 presenta las consolaciones de Dios como antídoto contra la ansiedad interior. El español ''consolaciones'' y ''consuelos'' convergen en este campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145450, 'spa', 'chacal', 'El chacal (Canis aureus), cánido salvaje aullador que habita ruinas y yermos, emblema bíblico de desolación total. Job se identifica con los chacales en su miseria (Job 30:29) y Miqueas aúlla como ellos en señal de duelo (Mi 1:8). Los oráculos proféticos de juicio emplean la presencia del chacal para señalar la ruina irreversible de una ciudad: Babilonia (Is 13:22; Jer 51:37), Edom (Is 34:13; 35:7), Hazor y Jerusalén (Jer 9:11; 10:22; 49:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145455, 'spa', 'Serpiente, culebra grande', 'Serpiente, culebra grande. Serpiente o culebra grande en el mundo natural, especialmente la serpiente de la señal del Éxodo. La vara de Aarón se convierte en un tannin ante Faraón (Éx 7:9-10), y los magos egipcios replican la hazaña (Éx 7:12). El Salmo 91:13 empareja tannin con pethen (cobra) en la promesa de pisar sobre criaturas peligrosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145456, 'spa', 'Dragón, monstruo del caos', 'Dragón, monstruo del caos. Dragón mitológico o monstruo del caos cósmico que representa poderes hostiles derrotados por Dios en la imaginería profética y apocalíptica. La ''serpiente veloz'' y la ''serpiente tortuosa'' de Isaías (Is 27:1), el adversario primordial aplastado junto con Rahab (Is 51:9), Faraón como el gran dragón en sus ríos (Ez 29:3; 32:2) y Nabucodonosor que ''me devoró como un dragón'' (Jer 51:34).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145458, 'spa', 'Monstruo marino, gran criatura del mar', 'Monstruo marino, gran criatura del mar. Gran criatura marina o monstruo del mar, parte del orden creado por Dios. Génesis 1:21 registra que Dios creó los ''grandes monstruos marinos'' — una imagen majestuosa, no hostil. Job 7:12 pregunta ''¿Soy yo el mar o un monstruo marino?'' y el Salmo 148:7 convoca a los tannin a alabar a Dios desde las profundidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145467, 'spa', 'Ordinal segundo', 'En Daniel 7:5, este ordinal identifica la segunda bestia en la secuencia visionaria: la criatura semejante a un oso que representa el segundo reino después de Babilonia. La forma femenina concuerda gramaticalmente con ''bestia'', mostrando la morfología estándar del arameo. El ordinal es fundamental para rastrear la sucesión de imperios en el marco apocalíptico de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145468, 'spa', 'Repetición temporal', 'En Daniel 2:7 marca la petición reiterada de los caldeos a Nabucodonosor: piden «por segunda vez» que les revele el sueño para poder interpretarlo. El adverbio destaca su insistencia y la tensión creciente del diálogo. Es vocabulario temporal básico que señala la repetición de una acción, esencial para seguir el intercambio entre el rey y sus consejeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145469, 'spa', 'Criatura inmunda no identificada', 'Las glosas interlingüísticas revelan profunda incertidumbre sobre la identidad de esta criatura. Traductores ingleses optan por ''lechuza común'', ''lechuza blanca'' o ''camaleón'' según el contexto. El español elige ''ibis'' y ''topo/sapo'', mientras francés y alemán preservan mayormente transliteraciones. Esto refleja el antiguo enigma: ¿cómo puede un término abarcar aves y reptiles? El hecho bíblico más claro es su impureza ritual—sea lo que sea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145470, 'spa', 'El sentido activo dominante en Piel expresa repulsión emocional visceral dirigid', 'El sentido activo dominante en Piel expresa repulsión emocional visceral dirigida hacia una persona o cosa. Deuteronomio 7:26 usa el infinitivo absoluto enfático (תַּעֵב תְּתַעֲבֶנּוּ) — ''lo aborrecerás por completo'' — para los ídolos traídos al hogar. Job 9:31 ofrece una imagen vívida: aunque Job se lavara, sus propias vestiduras lo ''aborrecerían''. El abanico de traducciones españolas — ''abomina'', ''aborrecen'', ''abominarás'' — refleja esta repugnancia profunda e instintiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145474, 'spa', 'El Nifal pasivo o estativo describe la condición de ser aborrecido o hallado det', 'El Nifal pasivo o estativo describe la condición de ser aborrecido o hallado detestable. Isaías 14:19 llama al rey de Babilonia ''un vástago abominado'' (נֵצֶר נִתְעָב) — arrojado de su sepulcro como un retoño aborrecido. Job 15:16 lo empareja con ''corrupto'' (נֶאֱלָח) para describir la condición humana. En 1 Crónicas 21:6, la orden del censo de David ''fue abominable'' a los ojos de Joab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145478, 'spa', 'El Hifil causativo desplaza el enfoque del sentimiento interno de disgusto a la ', 'El Hifil causativo desplaza el enfoque del sentimiento interno de disgusto a la ejecución externa de actos abominables. El Salmo 14:1 (= 53:1) declara que los necios ''han cometido obras abominables'', y 1 Reyes 21:26 describe a Acab actuando ''muy abominablemente'' al perseguir ídolos. Ezequiel 16:52 dice a Jerusalén que sus abominaciones superaron las de sus hermanas. El español ''hizo abominación'' capta la acción resultante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145488, 'spa', 'Una única aparición en Piel con matiz causativo en Ezequiel 16', 'Una única aparición en Piel con matiz causativo en Ezequiel 16:25: Jerusalén ''hizo abominable'' su hermosura ofreciéndose a todo transeúnte. No se trata de autoaborrecimiento sino del acto de convertir algo previamente bello en algo repulsivo para los demás. El español ''abominaste'' lo trata como acción reflexiva — hiciste de tu propia belleza una abominación — subrayando la trágica autodegradación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145491, 'spa', 'Extraviarse, errar moralmente (Qal) — Extravío moral y espiritual', 'Extraviarse, errar moralmente (Qal) — Extravío moral y espiritual: errar de los caminos de Dios, descarriarse éticamente. 19 apariciones en Qal. El salmista confiesa ''anduve errante como oveja perdida'' (Sal 119:176); los impíos ''se extravían desde el nacimiento'' (Sal 58:3); Israel es ''pueblo que yerra de corazón'' (Sal 95:10). Este sentido tiende el puente entre lo literal y lo figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145493, 'spa', 'Tambalearse, dar tumbos — Tambaleo o vacilación, especialmente por embriaguez', 'Tambalearse, dar tumbos — Tambaleo o vacilación, especialmente por embriaguez. 3 apariciones que describen movimiento inestable y torpe. Isaías 28:7 es el locus classicus: sacerdotes y profetas ''se tambalean con el vino'' y ''dan tumbos por la bebida fuerte.'' En Is 19:14 se hace a Egipto ''tambalearse en todo lo que hace'' como un borracho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145494, 'spa', 'Hacer errar, desviar (Hifil) — Hifil causativo', 'Hacer errar, desviar (Hifil) — Hifil causativo: hacer errar, desviar, engañar. 22 apariciones donde un agente causa activamente que otros se desvíen de la verdad, la justicia o el camino correcto. Manasés ''hizo errar a Judá'' (2 R 21:9; 2 Cr 33:9); Dios ''hace vagar a los consejeros'' como juicio (Job 12:24-25); los falsos profetas engañan al pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145500, 'spa', 'Vagar, deambular físicamente (Qal) — Deambular físicamente, vagar sin rumbo', 'Vagar, deambular físicamente (Qal) — Deambular físicamente, vagar sin rumbo. 6 apariciones en Qal donde el movimiento es literal y espacial. Agar vaga por el desierto (Gn 21:14), José encuentra a su hermano ''errante'' en el campo (Gn 37:15), los cuervos jóvenes ''vagan'' buscando alimento (Job 38:41) y los exiliados ''vagan por el desierto'' (Sal 107:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145511, 'spa', 'Ser engañado (Nifal) — Autoengaño pasivo o ser engañado', 'Ser engañado (Nifal) — Autoengaño pasivo o ser engañado. Una única aparición en Nifal en Job 15:31, donde Elifaz advierte: ''no confíe en la vanidad, engañándose a sí mismo.'' El matiz reflexivo-pasivo lo distingue tanto del extravío activo (sentido 1) como del voluntario (sentido 2): el sujeto es víctima de su propio engaño o del de otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145534, 'spa', 'Rey de Hamat', 'Nombre propio que identifica al rey de Hamat que establecio relaciones diplomaticas con David. Las cinco apariciones se concentran en dos relatos paralelos: 2 Samuel 8:9-10 (escrito Toi) y 1 Cronicas 18:9-10 (escrito Tou). La doble grafia entre Samuel y Cronicas es un caso bien documentado de variacion textual en nombres propios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145535, 'spa', 'Testimonio autoritativo', 'La evidencia multilingüe muestra traducción consistente como ''testimonio'' o ''témoignage'', con algunas versiones preservando la transliteración hebrea para honrar su peso técnico. El uso en Isaías lo empareja con torah, sugiriendo que el testimonio lleva autoridad profética. El uso en Rut indica costumbre legalmente reconocida. La palabra así abarca tanto testigo divino entregado por profetas como atestación humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145538, 'spa', 'Canal, conducto, zanja', 'Un paso de agua construido — ya sea un canal de riego (Ez 31:4), un canal para torrentes de lluvia abierto por Dios (Job 38:25), un conducto o acueducto cívico cerca de Jerusalén (2 R 18:17; Is 7:3; 2 R 20:20) o una zanja cavada alrededor de un altar (1 R 18:32, 35, 38). Las traducciones multilingües uniformes confirman un referente concreto único: un pasaje artificial para el agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145547, 'spa', 'Lo oculto y secreto', 'Las traducciones interlingüísticas enfatizan consistentemente lo oculto y secreto—español ''secretos'', francés ''secret'', alemán ''secrets''. Algunas versiones transliteran el hebreo, preservando su fuerza técnica. Job 11:6 habla de ''secretos de sabiduría'' que duplicarían lo que percibimos; Job 28:11 de cosas ocultas traídas a luz; Salmo 44:21 de pensamientos escondidos del corazón. El consenso multilingüe señala misterios profundos inaccesibles al conocimiento ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145548, 'spa', 'Deleite, placer refinado', 'Lujo, placer refinado y deleite exquisito. Abarca todo el campo semantico desde la indulgencia material (Pr 19:10; Ec 2:8) hasta el afecto tierno por los seres queridos (Mi 1:16; 2:9) y el deleite del amor (Cnt 7:6). El espanol ''deleite'' y ''delicias'' convergen en la nocion de un placer tanto sensorial como emocionalmente precioso, algo que se saborea mas que se consume.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145549, 'spa', 'Aflicción penitencial', 'En Esdras 9:5 señala el momento en que Esdras se levanta de su estado de aflicción o ayuno para orar en voz alta. Ha permanecido sentado con las vestiduras rasgadas, cargando simbólicamente la culpa del pueblo. La expresión marca el paso del duelo silencioso a la intercesión vocal, denotando la postura penitencial de identificación con el pecado de Israel mediante la abnegación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145550, 'spa', 'Taanac (topónimo)', 'El nombre propio que designa la ciudad cananea de Taanac en el valle de Jezreel. Las siete apariciones se refieren al mismo lugar. Los registros egipcios la escriben Ta-''a-na-k, confirmando su antigüedad. Aparece en la lista de conquistas de Josué (12:21), la asignación de Manasés (17:11; 21:25), la nota de que los cananeos no fueron expulsados (Jue 1:27), y memorablemente en el himno de victoria de Débora (Jue 5:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145555, 'spa', 'Poderío divino abundante', 'Designa un poderío abrumador o abundante, específicamente el poder divino concedido al pueblo de Dios. Su única aparición en el Salmo 68:35 lo empareja con עֹז (fuerza) para crear una expresión intensificada. La forma plural funciona como plural de intensidad o majestad, no indicando múltiples poderes discretos sino la plenitud y abundancia de la fuerza divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145556, 'spa', 'Vaina, funda de espada', 'Vaina, funda de espada. Vaina o funda — el estuche protector de una espada. Todas las apariciones en este sentido se dan en contextos militares que involucran desenvainar o envainar una hoja. David sacó la espada de Goliat ''de su vaina'' (1 S 17:51), la espada de Joab cayó ''de su vaina'' en el encuentro fatal con Amasa (2 S 20:8), y los oráculos de la espada de Ezequiel ordenan repetidamente que la hoja salga de su vaina o regrese a ella (Ez 21:3-5, 35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145557, 'spa', 'Navaja, cuchillo', 'Navaja, cuchillo. Navaja o cuchillo cortante — una hoja afilada usada para afeitar el cabello o cortar material. El voto nazareo estipula que ningún ta''ar pasará sobre la cabeza (Nm 6:5), y Números 8:7 prescribe afeitar todo el cuerpo con navaja para la consagración levítica. Isaías 7:20 lo usa figuradamente: el SEÑOR afeitará con una ''navaja alquilada'' (el rey de Asiria). El Salmo 52:2 compara una lengua engañosa con una navaja afilada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145567, 'spa', 'Pandero, tamboril — pequeño tambor de marco percutido con la palma o los dedos, ', 'Pandero, tamboril — pequeño tambor de marco percutido con la palma o los dedos, tocado prominentemente por mujeres en procesiones triunfales (Éx 15:20; Jue 11:34; 1 S 18:6), celebraciones comunitarias (Gn 31:27; Job 21:12), éxtasis profético (1 S 10:5) y alabanza litúrgica (Sal 81:3; 149:3; 150:4). Su cesación se convierte en señal profética de juicio (Is 24:8). Siempre agrupado con otros instrumentos — lira, arpa, flauta — confirmando su papel como pilar percusivo del conjunto musical de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145578, 'spa', 'Gloria, honor, majestad — Gloria, honor y majestad abstractos atribuidos a Dios,', 'Gloria, honor, majestad — Gloria, honor y majestad abstractos atribuidos a Dios, la realeza o una nación, con 28 apariciones. Deuteronomio 26:19 lo empareja con ''nombre'' (שֵׁם) en la frase ''para alabanza, fama y gloria.'' La oración de David en 1 Crónicas 29:11-13 atribuye תִּפְאֶרֶת a Dios junto con la grandeza y el poder. Se trata de un sentido elevado y no material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145579, 'spa', 'Belleza, esplendor — Belleza estética, esplendor visual o magnificencia exterior', 'Belleza, esplendor — Belleza estética, esplendor visual o magnificencia exterior de personas, lugares u objetos. Las vestiduras sacerdotales se hacen ''para gloria y hermosura'' (Éx 28:2, 40), y Ester 1:4 describe al rey mostrando ''el esplendor de su excelente majestad.'' El Salmo 71:8 pide a Dios que llene la boca del salmista de alabanza y ''tu gloria todo el día.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145593, 'spa', 'Ornamento, galas — Objetos ornamentales concretos o galas decorativas, el extrem', 'Ornamento, galas — Objetos ornamentales concretos o galas decorativas, el extremo más tangible del espectro semántico. Isaías 3:18 lo usa para los adornos de los tobillos de las mujeres (''las galas de los ajorcas''), e Isaías 52:1 ordena a Sion que se vista con ''tus vestiduras hermosas.'' Este sentido trata תִּפְאֶרֶת como algo que se puede vestir o exhibir, en lugar de una cualidad abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145614, 'spa', 'Manzano, manzana (fruto)', 'Árbol frutal fragante y su fruto, tradicionalmente la manzana (Malus domestica), empleado tanto literal como figuradamente. El árbol aparece como símbolo de la sombra y dulzura del amado (Cnt 2:3; 8:5), mientras que el fruto transmite refrigerio y deleite (Cnt 2:5). Las traducciones en diversas lenguas — español ''manzano'', francés ''pommier'' — apuntan uniformemente a la manzana, aunque el campo aromático más amplio admite otras identificaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145620, 'spa', 'Nombre propio personal', 'Nombre de un descendiente en el linaje de Judá, identificado específicamente como hijo de Hebrón en la genealogía calebita. Su única aparición en 1 Crónicas 2:43 lo sitúa dentro de los registros tribales. Las traducciones generalmente transliteran el nombre (en español «Tapúaj»), aunque algunas fuentes lo ponen entre corchetes, posiblemente reflejando incertidumbre textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145621, 'spa', 'Toponimo cananeo', 'Tapua: nombre geografico propio de ciudades cananeas conquistadas y asignadas a Israel. Las cinco apariciones (Jos 12:17; 15:34; 16:8; 17:8 dos veces) funcionan como referencias topograficas. Las traducciones transliteran de forma uniforme — espanol ''Tapua'', ingles ''Tappuah'' —, confirmando que se trata de un nombre propio estable que no requiere desambiguacion semantica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145622, 'spa', 'Dispersión por juicio', 'Se refiere al acto o estado de ser dispersado, empleado en el contexto del juicio divino contra líderes infieles. En Jeremías 25:34 el término aparece con sufijo de segunda persona plural («vuestras dispersiones»), sugiriendo que es la propia dispersión de los dirigentes la que está en perspectiva. Los problemas textuales dificultan la interpretación precisa, pero el campo semántico involucra claramente una dispersión forzada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145623, 'spa', 'Piezas de ofrenda', 'Probablemente se refiere a piezas horneadas o desmenuzadas de una ofrenda de cereal, aunque el significado preciso sigue siendo debatido. El contexto de Levítico 6:21 describe la preparación de una ofrenda vegetal que debe partirse o dividirse. Las tradiciones en español e inglés («tortas cocidas», «baked pieces») sugieren una conexión con el proceso de horneado, mientras que la forma hebrea incierta ha dado lugar a diversas propuestas eruditas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145625, 'spa', 'Enjalbegadura / Cal', 'Enjalbegadura, revestimiento de cal aplicado para ocultar debilidades estructurales. Las cinco apariciones se concentran en Ezequiel (13:10, 11, 14, 15; 22:28), donde funciona como material literal y como metáfora profética del engaño tranquilizador. El español ''cal'', el inglés ''whitewash'' y el alemán ''Tünche'' convergen en un tratamiento superficial que esconde lo que hay debajo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145626, 'spa', 'Topónimo bíblico', 'Nombre propio que designa un lugar en la región del Arabá donde Moisés se dirigió a Israel. La única referencia en Deuteronomio 1:1 cumple la función de proveer contexto geográfico para el escenario del libro. Las identificaciones modernas han sugerido Tafileh en Jordania, aunque los especialistas debaten la correspondencia fonética. Las traducciones transliteran el nombre de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145627, 'spa', 'Indecoro moral', 'La evidencia multilingüe muestra interpretación diversa: el inglés da ''folly'', ''unseemliness'', ''wrong''; el español ''insensatez''; pero curiosamente algunas versiones francesas y alemanas traducen como ''oración'' (prière, Gebet), aparentemente confundiendo esta raíz con una forma similar. El sentido correcto, apoyado por el contexto en Job y Jeremías, es indecoro moral. Job se negó a atribuir impropiedad moral a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145628, 'spa', 'Oración, súplica — Oración o súplica elevada a Dios, que abarca la petición pers', 'Oración, súplica — Oración o súplica elevada a Dios, que abarca la petición personal (Sal 4:1; 2 S 7:27), el ruego intercesorio en favor de otros (Jer 7:16; 2 R 19:4) y la oración litúrgica corporativa en el templo (1 R 8:38, 54). La construcción בֵּית תְּפִלָּה, ''casa de oración'' (Is 56:7), extiende el término para designar el propio espacio sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145646, 'spa', 'Horror infundido', 'Describe la cualidad de inspirar horror, pavor o temor, específicamente el terror que una persona o nación proyecta hacia el exterior. En Jeremías 49:16 se refiere a la supuesta capacidad de Edom para intimidar a otros, la cual resulta ilusoria ante el juicio de Dios. El término conlleva un fuerte componente psicológico: el estremecimiento o la reacción de miedo que alguien provoca en los demás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145649, 'spa', 'Coser o zurcir', 'Abarca tanto el oficio práctico de unir telas con aguja e hilo como sus aplicaciones metafóricas. El relato de Génesis marca el origen de la confección humana como respuesta a la vergüenza. La imagen de Job intensifica su sufrimiento al no solo vestir cilicio, sino tenerlo cosido a su propia carne. El pasaje de Ezequiel sugiere la costura ritual de amuletos u objetos mágicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145650, 'spa', 'Qal', 'Qal: agarrar, capturar — El sentido activo dominante del Qal: agarrar, capturar o asir por la fuerza. 43 apariciones que abarcan conquista militar, arresto y aprehensión física. Incluye agarrar a individuos (Gn 39:12; Dt 21:19, padres que asen a un hijo rebelde), capturar ciudades (2 R 14:13; 18:13, Senaquerib tomando las ciudades fortificadas de Judá) y aprehender a profetas (Jer 37:14, el arresto de Jeremías).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145656, 'spa', 'Nifal', 'Nifal: ser apresado, ser capturado — El Nifal pasivo: ser apresado, atrapado o capturado. 15 apariciones concentradas en los oráculos de juicio de Jeremías. Ciudades que ''son capturadas'' (Jer 48:41, Queriot; 50:2, Babilonia), reyes que ''son atrapados'' (Jer 34:3, Sedequías) e individuos ''apresados'' en pecado oculto (Nm 5:13). El patrón teológico es llamativo: ser tomado por el enemigo es consecuencia del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145667, 'spa', 'Qal', 'Qal: manejar, empuñar — Participio Qal que significa manejar, empuñar o tocar. 5 apariciones que enfatizan el uso hábil más que la captura. Génesis 4:21 presenta a Jubal como ''padre de todos los que tocan la lira y la flauta''; Jeremías lo usa para quienes ''manejan'' la ley (Jer 2:8) y guerreros que ''empuñan'' el arco (Jer 46:9; 50:16; Am 2:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145683, 'spa', 'Ser asible (proverbial) — Un sentido proverbial en Proverbios 30', 'Ser asible (proverbial) — Un sentido proverbial en Proverbios 30:28: la lagartija ''se puede atrapar con las manos'' y sin embargo habita en palacios de reyes. El verbo describe una potencial asibilidad: una criatura que, pese a poder ser atrapada, logra acceder a los lugares más elevados. Esta aparición se sitúa entre los sentidos 1 y 3, combinando la asibilidad física con la ironía sapiencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145702, 'spa', 'Estar recubierto — Una aparición única en Habacuc 2', 'Estar recubierto — Una aparición única en Habacuc 2:19 que describe un ídolo ''recubierto'' (תָּפוּשׂ) de oro y plata. El significado raíz de ''asir'' se extiende a recubrir o revestir: el oro ''agarra'' la madera. Este uso artesanal especializado aparece solo aquí en la Biblia hebrea, representando una genuina extensión semántica desde la captura hacia el revestimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145704, 'spa', 'Escupir con desprecio', 'Se refiere al acto de escupir, particularmente en el rostro de alguien como gesto de desprecio. En Job 17:6, Job lamenta haberse convertido en «un escupitajo en la cara», esto es, objeto de escarnio público sobre quien la gente escupe. Este acto fisiológico conlleva fuertes connotaciones culturales de repugnancia y rechazo total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145705, 'spa', 'Tofet (topónimo)', 'El nombre propio Tofet (o con artículo, ha-Tofet), que designa el sitio cultual específico en el Valle de Ben-Hinom donde se practicaba el sacrificio de niños (Jer 7:31; 2 R 23:10). Jeremías profetizó que sería renombrado ''Valle de la Matanza'' y se convertiría en fosa común (Jer 7:32; 19:6, 11). Isaías 30:33 extiende la imagen metafóricamente a una pira divina preparada para Asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145710, 'spa', 'Lugar de juicio', 'Funciona como topónimo (posiblemente variante de Tofet) utilizado figuradamente para expresar juicio divino y destrucción por fuego. Isaías 30:33 emplea este lugar como símbolo de la inminente destrucción de Asiria: un sitio de incineración preparado por Dios. Aunque existen cuestiones textuales sobre la forma precisa, el contenido semántico es claro: un lugar de juicio ardiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145713, 'spa', 'Anticipación confiada o expectativa dirigida hacia un resultado futuro, abarcand', 'Anticipación confiada o expectativa dirigida hacia un resultado futuro, abarcando la confianza teológica en Dios y la aspiración humana cotidiana. En la literatura sapiencial, la esperanza separa al justo del impío (Pr 10:28; 11:7; Job 8:13). Jeremías promete ''esperanza para tu porvenir'' a las madres en el exilio (Jer 31:17), y Oseas convierte el Valle de Acor en ''puerta de esperanza'' (Os 2:17). Lamentaciones 3:29 insta a la esperanza silenciosa, mientras Proverbios 23:18 y 24:14 la asocian con un futuro que no será cortado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145726, 'spa', 'Capacidad de resistir', 'Denota la capacidad de mantenerse firme o sostener la propia posición, especialmente en contextos militares o de adversidad. En Levítico 26:37, Dios advierte que la desobediencia al pacto resultará en que Israel no tenga תְּקוּמָה ante sus enemigos: carecerán de la fuerza para resistir o perseverar. El término implica más que una postura física; abarca el poder de soportar el ataque y el ánimo para no ceder terreno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145727, 'spa', 'Oposición activa', 'Forma participial que describe a quienes se levantan en oposición activa o rebelión, específicamente contra el Señor. El Salmo 139:21 emplea este término para referirse a los enemigos de Dios que se alzan en desafío. El tronco Hitpolel sugiere una acción intensiva y decidida: no son oponentes pasivos sino insurgentes activos que deliberadamente se posicionan contra la autoridad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145728, 'spa', 'Trompeta o toque', 'Se refiere a una trompeta o cuerno de carnero usado para dar señales, o posiblemente al acto mismo de hacerlo sonar. Ezequiel 7:14 describe el toque de trompeta en el contexto de preparación para la guerra, aunque el análisis gramatical exacto es debatido. Si se lee como sustantivo, designa el instrumento mismo (similar al שׁוֹפָר); si como infinitivo, designa la acción de tocarlo. En ambos casos, el dominio semántico involucra señalización militar y alarma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145729, 'spa', 'Tecoa (topónimo)', 'El nombre propio que designa la ciudad judía de Tecoa (actual Khirbet Tequ''a). Las siete apariciones se refieren al mismo lugar. Las notas genealógicas de 1 Crónicas 2:24 y 4:5 personifican la ciudad como «hijo» de Asjur, reflejando el modismo bíblico común de ancestro-como-fundador-de-ciudad. El topónimo se preserva con ligera adaptación fonética en las traducciones españolas como Tecoa o Teqoa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145733, 'spa', 'Tecoíta (gentilicio)', 'Adjetivo gentilicio que significa ''tecoíta'', persona originaria de Tecoa. Sus siete apariciones comparten este sentido demónimico, variando solo en género y número. La forma femenina en 2 Samuel 14:4, 9 describe a la mujer sabia; el masculino singular en 2 Samuel 23:26 identifica al guerrero Ira, y el plural en Nehemías 3:5, 27 designa a un grupo cívico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145736, 'spa', 'Ciclo cumplido', 'Enfatiza la completitud ciclica mas que el mero transcurso del tiempo: la revolucion completa que retorna al punto de partida. El circuito solar del Salmo 19:6 ofrece la metafora cosmica: asi como el sol completa su arco por los cielos sin que nada escape a su calor, la ley de Dios abarca toda la existencia humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145737, 'spa', 'Más fuerte que otro', 'Describe a alguien que es más fuerte o más poderoso en sentido comparativo, específicamente más fuerte que el ser humano que pudiera intentar contender o disputar. Eclesiastés 6:10 emplea este aramaísmo para afirmar la limitación humana: nadie puede contender con ''el que es más fuerte que él''. El contexto sugiere soberanía divina o destino inexorable, aquello que ha sido determinado y no puede ser cuestionado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145738, 'spa', 'Fuerte / Poderoso', 'Fuerte, poderoso, imponente: describe entidades que imponen temor o reverencia. Se aplica a un reino que tritura como hierro (Dn 2:40, 42), una bestia aterradora (Dn 7:7), señales divinas (Dn 4:3) y reyes dominantes (Esd 4:20). El español distingue ''fuerte'' de ''poderoso'', reflejando el espectro desde la fuerza bruta hasta el poderío divino que abarca este adjetivo arameo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145739, 'spa', 'Pesado en juicio', 'Perfecto pasivo arameo que significa ''has sido pesado'', usado en el contexto de juicio y evaluación divina. Daniel 5:27 emplea este término para anunciar que el rey Belsasar ha sido sometido a la balanza de Dios, metáfora de una evaluación moral y espiritual. La imagen de pesar sugiere precisión, imparcialidad y carácter definitivo: las obras y el carácter de la persona son medidos con exactitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145741, 'spa', 'Enderezar, ordenar', 'Las glosas interlingüísticas enfatizan consistentemente el enderezamiento y arreglo: español ''enderezar'', francés ''redresser'', alemán ''gerade machen''. Los tres pasajes de Eclesiastés exploran la tensión entre la soberanía divina sobre lo torcido o recto y la responsabilidad humana de ordenar la sabiduría. El verbo aparece en formas infinitivas discutiendo la capacidad o incapacidad de enderezar (1:15, 7:13) y describiendo la ordenación activa de proverbios (12:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145742, 'spa', 'Restauración y restablecimiento', 'Forma Hofal aramea que significa «fui restablecido» o «fui restaurado», indicando la restitución al orden y posición debidos. En Daniel 4:36, Nabucodonosor describe su retorno a la cordura y su reinstauración en el trono tras un período de locura. El Hofal pasivo enfatiza la acción divina: Dios lo restauró y lo puso en orden nuevamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145743, 'spa', 'Tocar trompeta/cuerno — El sentido dominante', 'Tocar trompeta/cuerno — El sentido dominante: soplar un instrumento de viento — shofar, trompeta o cuerno — para producir una señal, convocatoria, alarma o acto de adoración. Con 49 apariciones, abarca los toques de trompeta en el Sinaí, el shofar en Jericó (Jos 6:4-20), los cuernos de señal de Gedeón (Jue 7:18-22) y el toque litúrgico en días de fiesta (Nm 10:3-10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145752, 'spa', 'Clavar, hundir (estaca, arma) — Clavar, hundir o fijar un objeto físico en algo', 'Clavar, hundir (estaca, arma) — Clavar, hundir o fijar un objeto físico en algo: una estaca de tienda en el suelo (Gn 31:25, plantando una tienda), una estaca a través de un cráneo (Jue 4:21, Jael y Sísara), un arma en un cuerpo (Jue 3:21, la espada de Ehud; 2 S 18:14, los dardos de Joab en Absalón).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145755, 'spa', 'Batir palmas (celebración) — Batir las palmas en celebración, alabanza o burla', 'Batir palmas (celebración) — Batir las palmas en celebración, alabanza o burla. Sal 47:1: ''¡Pueblos todos, batid las manos!'' Nah 3:19: todos los que oyen la noticia de la caída de Nínive baten palmas. Solo dos apariciones se agrupan aquí, pero el sentido es distinto del de dar fianza (sentido 3) porque no hay compromiso contractual, solo gesto expresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145756, 'spa', 'Dar la mano (como fianza) — Estrechar o dar la mano como gesto de hacer una prom', 'Dar la mano (como fianza) — Estrechar o dar la mano como gesto de hacer una promesa, garantía o fianza — un acto comercial contra el que Proverbios advierte insistentemente. ''Si has dado la mano en prenda por tu prójimo'' (Pr 6:1); ''el que da garantía por un extraño lo pagará'' (Pr 11:15; 17:18; 22:26). Job 17:3 pide a Dios mismo que sea fiador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145758, 'spa', 'Ser tocado (pasivo de trompeta) — El Nifal pasivo', 'Ser tocado (pasivo de trompeta) — El Nifal pasivo: una trompeta o cuerno es tocado, sin especificar quién lo toca. Is 27:13: ''En aquel día se tocará una gran trompeta''; Am 3:6: ''¿Se toca la trompeta en la ciudad y el pueblo no se alarma?'' Las dos apariciones portan un peso escatológico o de señal de alarma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145789, 'spa', 'Toque de cuerno', 'Designa el toque o sonido producido al soplar un cuerno o trompeta, especialmente el shofar. El Salmo 150:3 prescribe la adoración «con sonido de shofar», enfatizando el elemento auditivo de la alabanza. La forma constructa תֵּקַע vincula este sustantivo a שׁוֹפָר, especificando el toque característico de dicho instrumento: fuerte, resonante y penetrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145790, 'spa', 'Dominar por fuerza', 'Denota el ejercicio de una fuerza superior para someter o vencer. En Job, el uso es teologico: el poder irresistible de Dios sobre los mortales. Eclesiastes lo aplica al conflicto humano, donde la superioridad numerica importa (''cordon de tres hilos no se rompe pronto'' sigue a la mencion de dominar en 4:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145791, 'spa', 'Fortalecerse / Imponer', 'Hacerse fuerte, volverse poderoso o endurecerse (tallo Pe''al). Describe el crecimiento en poder: el árbol simbólico (Dn 4:11, 20), la autoridad real (Dn 4:22) y el endurecimiento soberbio (Dn 5:20). El infinitivo Pael en Dn 6:7 extiende el significado a ''imponer, hacer riguroso'', aplicando la fuerza a un decreto legal. Doble registro: crecimiento en poder y aplicación coercitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145792, 'spa', 'Poder y poderío', 'Sustantivo arameo que denota poder, fuerza o poderío, específicamente la capacidad de lograr y edificar mediante la fuerza. Daniel 4:30 emplea este término en la proclama orgullosa de Nabucodonosor: «con la fuerza de mi poder he edificado este reino». La frase constructa intensifica el sentido de poder personal. El término aparece en contextos que contrastan el poder humano con el divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145793, 'spa', 'Fuerza otorgada por Dios', 'Sustantivo enfático arameo que significa «la fuerza» o «el poderío», referido al poder real concedido por Dios. Daniel 2:37 lo enumera entre los atributos que Dios otorgó a Nabucodonosor: reino, poder, fuerza y gloria. La forma enfática תָּקְפָּא (con terminación definida) especifica esta como la fuerza particular y reconocida del rey, cuyo origen es un don divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145794, 'spa', 'Poder real, autoridad', 'La evidencia multilingüe muestra glosas que enfatizan autoridad y poder: español ''autoridad'' y ''poder'', francés ''puissance''. Algunas versiones preservan la transliteración hebrea, marcándola como término técnico para poderío real. Los tres casos aparecen en textos bíblicos tardíos (Ester, Daniel) tratando contextos imperiales persas, sugiriendo que puede ser un préstamo o término especializado para poder político activamente ejercido en decretos y campañas militares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145795, 'spa', 'Topónimo en Benjamín', 'Nombre de lugar que designa una ciudad dentro de la herencia tribal de Benjamín. Su única aparición en Josué 18:27 la sitúa en la geografía administrativa del Israel primitivo, aunque su identificación moderna precisa sigue siendo incierta. Las traducciones en diversas lenguas transliteran consistentemente el nombre, tratándolo como un topónimo fijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145796, 'spa', 'Prole despectiva', 'Designa una cría, prole o progenie, usado despectivamente en Números 32:14 para caracterizar a los rubenitas y gaditas como ''cría de hombres pecadores''. El término subraya la continuidad hereditaria del pecado: son descendientes que perpetúan la rebeldía de sus padres. El sentido raíz de ''aumento'' adquiere coloración moral negativa: son multiplicación de transgresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145797, 'spa', 'Interés usurario', 'Incremento financiero o ganancia usuraria obtenida mediante préstamos, siempre en el contexto de la ética económica. El término aparece junto a neshekh en seis de sus siete ocurrencias, conformando una prohibición integral contra el interés abusivo. Levítico 25:36 lo prohíbe categóricamente; Ezequiel 18:8, 13, 17 y 22:12 lo tratan como criterio de rectitud; Proverbios 28:8 promete redistribución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145801, 'spa', 'Enseñar a caminar', 'Significa ''enseñé a caminar'' o ''adiestré a dar pasos'', representando el tierno cuidado de Dios al enseñar a Israel (Efraín) a caminar, como un padre enseña a un niño pequeño. Oseas 11:3 emplea este raro verbo denominativo para evocar instrucción paternal íntima: tomar al niño de los brazos, guiar cada paso, brindar estabilidad. La forma verbal intensiva sugiere acción repetida y paciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145802, 'spa', 'Traducido, interpretado', 'Participio pasivo arameo que significa ''traducido'' o ''interpretado'', referido a verter un documento de una lengua a otra. Esdras 4:7 describe una carta escrita en escritura aramea y ''traducida'' al arameo, indicando comunicación administrativa bilingüe. Este verbo es la fuente etimológica de ''Targum'', las versiones arameas de las Escrituras hebreas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145803, 'spa', 'Sueño profundo divino', 'Sueño profundo impuesto divinamente que produce inconsciencia semejante al trance, distinto del descanso ordinario. Involucra siempre agencia sobrenatural: Dios ''hace caer'' este sueño sobre la persona (Gn 2:21; 15:12; 1 Sam 26:12) o desciende durante visiones nocturnas (Job 4:13; 33:15). Proverbios 19:15 lo extiende al sopor de la pereza e Isaías 29:10 lo emplea como metáfora de insensibilidad espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145808, 'spa', 'Contribución, ofrenda sagrada — El sentido general de una contribución voluntari', 'Contribución, ofrenda sagrada — El sentido general de una contribución voluntaria o don sagrado: cualquier cosa separada de las posesiones propias y dedicada a Dios o al santuario. Este es el uso dominante en el Pentateuco, donde תְּרוּמָה cubre las donaciones para el tabernáculo (Éx 25:2; 35:5), las primicias agrícolas (Nm 15:19-21) y la porción de tierra sagrada en la visión del templo de Ezequiel (Ez 45:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145815, 'spa', 'Ofrenda elevada, porción sacerdotal — El término técnico sacerdotal para la porc', 'Ofrenda elevada, porción sacerdotal — El término técnico sacerdotal para la porción físicamente elevada o separada de un sacrificio, cosecha o diezmo y asignada a los sacerdotes como su parte legítima. Esta ofrenda elevada se distingue en pasajes como Éx 29:27-28 y Nm 18:8-11, donde aparece junto a la ofrenda mecida (תְּנוּפָה). El gesto ritual de elevación consagra la porción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145837, 'spa', 'Exacciones, tributos (irónico) — Un uso singular en Pr 29', 'Exacciones, tributos (irónico) — Un uso singular en Pr 29:4 donde la palabra parece denotar exacciones forzosas, sobornos o tributos injustos: ''el hombre de tributos destruye la tierra.'' El desplazamiento de contribución sagrada a extracción corrupta puede ser un juego de palabras irónico, aplicando el vocabulario de la ofrenda consagrada a su opuesto moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145839, 'spa', 'Ofrenda complementaria', 'Designa una contribución u ofrenda, específicamente una subdivisión o porción complementaria dentro de una asignación sagrada mayor. Ezequiel 48:12 emplea este término (o posiblemente una forma corrupta de תְּרוּמָה) para describir la porción sacerdotal de tierra en la visión escatológica del templo. La forma denominativa sugiere ''lo que pertenece a una contribución'': una ofrenda secundaria o subporción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145840, 'spa', 'El grito de guerra o señal de alarma — un clamor o toque de trompeta en contexto', 'El grito de guerra o señal de alarma — un clamor o toque de trompeta en contexto de batalla, movilización militar o advertencia. Números 10:5-6 prescribe la תְּרוּעָה tocada con trompetas de plata como señal para levantar el campamento, mientras Amós 1:14 y Sofonías 1:16 la asocian con el terror del juicio divino. El inglés ''alarm'', el español ''alarma'' y el francés ''alarme'' convergen en la lectura de señal militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145842, 'spa', 'Un grito fuerte o clamor general — una vociferación colectiva no necesariamente ', 'Un grito fuerte o clamor general — una vociferación colectiva no necesariamente ligada a la alegría ni a la guerra, pero cargada de intensidad vocal. Cuando el arca entró en el campamento israelita, los filisteos oyeron la תְּרוּעָה y temblaron (1 S 4:5-6). Josué 6:5 y 6:20 describen el grito del pueblo que acompañó el toque de trompeta en Jericó. El español ''grito'' y el francés ''cri'' confirman el sentido de una explosión sonora cruda y colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145847, 'spa', 'La aclamación jubilosa — un grito de triunfo, júbilo o alabanza dirigido a Dios ', 'La aclamación jubilosa — un grito de triunfo, júbilo o alabanza dirigido a Dios en adoración y celebración. Números 23:21 habla de ''aclamación de rey'' entre Israel, y el Salmo 27:6 promete sacrificios ''con gritos de júbilo''. El español ''júbilo'', el francés ''acclamation'' y el alemán ''Jauchzen'' apuntan a un registro emocionalmente positivo y doxológico que distingue este sentido del contexto bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145863, 'spa', 'Sanidad, remedio', 'Se refiere a sanidad, cura o propósito medicinal, específicamente la función restauradora de las hojas en la visión del templo de Ezequiel. Ezequiel 47:12 describe árboles cuyas hojas son לִתְרוּפָה (''para sanidad''), indicando propiedades terapéuticas. El sustantivo enfatiza propósito o función: estas hojas existen para sanar, restaurar y curar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145864, 'spa', 'Árbol para tallado', 'Designa una especie arbórea, probablemente un ciprés o tipo de encina, utilizada como madera para tallar ídolos. En Isaías 44:14 se describe satíricamente a un fabricante de ídolos que escoge este árbol junto con robles y cedros. La madera debía ser dura y trabajable, lo que explica las diversas identificaciones propuestas. Lo determinante es su función: madera valiosa empleada absurdamente para la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145865, 'spa', 'Téraj (nombre propio)', 'Téraj (nombre propio). El nombre propio Téraj, que identifica dos referentes: (a) el padre de Abraham, hijo de Nacor, quien partió de Ur y se estableció en Harán donde murió (Gn 11:24-32; 1 Cr 1:26; Jos 24:2), y (b) una estación israelita en el desierto entre Tahat y Mitca en la ruta del Éxodo (Nm 33:27-28). Las once apariciones genealógicas se concentran en Génesis 11, mientras que las dos referencias al campamento aparecen en Números 33.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145868, 'spa', 'Nombre propio', 'Nombre personal de un descendiente en el linaje de Caleb, específicamente hijo o hija de Caleb y su concubina Maaca según 1 Crónicas 2:48. La única aparición bíblica no permite esclarecer su etimología, y el género resulta incierto. Las transliteraciones griegas varían considerablemente, lo que sugiere que el nombre ya era infrecuente o difícil de pronunciar en la antigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145869, 'spa', 'Numeral ''dos''', 'Funciona como el numeral basico ''dos'' en textos administrativos y narrativos del arameo biblico. Cuando se combina con ''diez'' (עֲשַׂר), forma ''doce,'' el numero de machos cabrios y toros ofrecidos en la dedicacion del templo (Esdras 6:17). Las formas con flexion de genero reflejan la gramatica estandar del semitico noroccidental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145870, 'spa', 'Engaño profético', 'Designa el engaño o la representación fraudulenta, específicamente las mentiras fabricadas por falsos profetas que atribuyen origen divino a sus propias invenciones. Jeremías 14:14 condena a profetas que hablan ''el engaño de su corazón'', enfatizando el origen interno de la falsedad (no proviene de Dios) y su carácter deliberadamente fraudulento. El término implica culpabilidad moral plena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145871, 'spa', 'Engaño o topónimo', 'Término incierto que posiblemente significa ''con engaño'' o ''traidoramente'', aunque es probable una corrupción textual. Si la lectura masorética es correcta, Jueces 9:31 describiría a mensajeros que acuden ''con engaño'' para informar a Abimelec sobre la presencia de Gaal. Sin embargo, la forma es morfológicamente extraña y el contexto sugiere que el topónimo Arumá (v. 41) es más probablemente la lectura original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145872, 'spa', 'Engaño / Perfidia', 'Engaño, perfidia: falsedad persistente arraigada en el corazón o la lengua. Aparece en contextos proféticos y sapienciales: emparejada con שֶׁקֶר (''falsedad'') en Sal 119:118 y Jer 23:26, con כָּזָב (''mentira'') en Sof 3:13, y describiendo apostasía incorregible en Jer 8:5. El español ''engaño'' y el inglés ''deceit'' convergen en señalar una falsedad deliberada que permea la voluntad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145873, 'spa', 'Mástil, poste solitario', 'Las glosas interlingüísticas traducen consistentemente como ''mast'' o ''mástil'', aunque algunas preservan transliteraciones. El español y francés enfatizan particularmente el sentido náutico mientras también usan términos como ''pilier'' (pilar). Los pasajes de Isaías usan imaginería de barcos metafóricamente: un pueblo reducido a un solo poste en un monte donde antes había ejércitos. Ezequiel da el sentido marítimo literal. La evidencia multilingüe confirma tanto el uso náutico como el metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145875, 'spa', 'Porteros del templo', 'Sustantivo plural arameo que significa ''porteros'' o ''guardianes de las puertas'', referido al personal del templo que custodia las entradas y controla el acceso. Esdras 7:24 enumera a los porteros entre el personal exento de tributación imperial, junto a sacerdotes, levitas y cantores. El término designa una clase reconocida de funcionarios sagrados responsables de mantener los límites del recinto sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145876, 'spa', 'Tambaleo, aturdimiento', 'Las glosas multilingües enfatizan tambaleo y aturdimiento: español ''aturdimiento'' y ''tambaleo'', francés ''étonnement'' (asombro), alemán ''staggering''. La imagen consistente entre lenguas es pérdida de equilibrio. Tanto Isaías como Salmos emparejan esta palabra con beber, usando imaginería de vino/copa para retratar juicio divino que desorienta. La evidencia interlingüística confirma la metáfora de embriaguez: juicio divino que produce pérdida de capacidad de estar firme o pensar claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145877, 'spa', 'Clan escribal quenita', 'Nombre plural de familia que designa a un clan quenita de escribas, una de las tres familias que habitaban en Jabes segun 1 Cronicas 2:55. Los tirateos descendian de Hamat y estaban vinculados a la casa de Recab. La forma plural senala que se trata de un grupo familiar, no de un individuo. El termino funciona tanto genealogica como profesionalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145878, 'spa', 'Terafines (ídolos domésticos)', 'Terafines (ídolos domésticos). Figurillas de ídolos domésticos asociadas con la adivinación y la práctica religiosa familiar. Varían en tamaño desde lo suficientemente pequeñas para esconderlas en una silla de camello (Gn 31:34) hasta figuras de forma aproximadamente humana (1 S 19:13, 16). Se mantenían en santuarios privados junto a efods (Jue 17:5; 18:14-20), se consultaban como oráculos (Ez 21:26; Zac 10:2) y fueron repetidamente condenados por los reformadores (1 S 15:23; 2 R 23:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145883, 'spa', 'Tirsa (nombre propio) — nombre propio usado tanto para una mujer como para una c', 'Tirsa (nombre propio) — nombre propio usado tanto para una mujer como para una ciudad. Como nombre personal, una de las cinco hijas de Zelofehad cuya reclamación de herencia estableció un precedente legal para los derechos de propiedad femenina (Nm 26:33; 27:1; 36:11; Jos 17:3). Como topónimo, antigua ciudad cananea (Jos 12:24) que sirvió como capital del reino del norte desde Jeroboam hasta los primeros años del reinado de Omri (1 R 14:17–16:23). Cantar de los Cantares 6:4 celebra a la amada como «hermosa como Tirsa», colocando la ciudad junto a Jerusalén como sinónimo de hermosura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145891, 'spa', 'Berilo o crisólito', 'Piedra preciosa amarillo-verdosa, probablemente crisólito o berilo, apreciada por su tono dorado luminoso. Aparece en el pectoral sacerdotal (Éx 28:20; 39:13), en la visión de Ezequiel donde las ruedas brillan ''como piedra de Tarsis'' (1:16; 10:9), en la teofanía de Daniel (10:6), en los adornos de Tiro (Ez 28:13) y en el Cantar de los Cantares (5:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145896, 'spa', 'Un lugar marítimo distante, muy probablemente Tartesos en el sur de España, que ', 'Un lugar marítimo distante, muy probablemente Tartesos en el sur de España, que representaba el extremo occidental de las rutas comerciales del mundo antiguo. Genealógicamente es descendiente de Javán (Gn 10:4; 1 Cr 1:7). ''Naves de Tarsis'' se convirtió en un término genérico para grandes embarcaciones de alta mar, asociadas con los lucrativos viajes de Salomón (1 R 10:22) y el intento fallido de Josafat (1 R 22:48). Proféticamente, estas naves simbolizan el orgullo humano que será humillado (Is 2:16; 23:1, 14). Jonás huyó a Tarsis para escapar de la presencia del SEÑOR (Jon 1:3), y el Salmo 72:10 vislumbra a los reyes de Tarsis trayendo tributo al Mesías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145901, 'spa', 'Título gubernatorial', 'Tirsata: título gubernatorial de origen persa que significa ''el venerado'' o ''Su Excelencia'', aplicado al gobernador de Judá en el periodo postexílico. Las cinco apariciones (Esd 2:63; Neh 7:65, 70; 8:9; 10:1) llevan el artículo hebreo הַ, marcándolo como designación oficial reconocida. El español ''el gobernador'' y el inglés ''the Tirshatha'' identifican un cargo persa investido de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145903, 'spa', 'Deidad avea', 'Nombre divino de una deidad adorada por los aveos, mencionada en 2 Reyes 17:31 como uno de los dioses extranjeros introducidos en la tierra de Israel tras las deportaciones asirias. Tartac aparece junto a Nibhaz, otra deidad avea, en el catalogo de practicas culticas sincretistas. Su nombre no ha sido identificado con certeza en fuentes extrabliblicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145904, 'spa', 'Clamor y estruendo', 'Abarca sonidos fuertes, a menudo confusos o múltiples: gritos de celebración, bullicio urbano, rugido del trueno. Las traducciones «alboroto» y «aclamaciones» reflejan tanto el desorden como la solemnidad. En Job la imagen de la tormenta evoca un tumulto natural abrumador, mientras que en Zacarías se trata de aclamación ritual. El pasaje del asno montés contrasta la libertad salvaje con las órdenes vociferadas del capataz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145905, 'spa', 'El tisbita (gentilicio)', 'Adjetivo gentilicio que denota procedencia de la ciudad de Tisbe (probablemente en Galaad), usado únicamente como epíteto del profeta Elías. Todas las apariciones siguen la fórmula fija ''Elías el tisbita'' a lo largo de 1-2 Reyes (p. ej., 1 Re 17:1; 2 Re 1:8). La LXX lo traduce como ὁ Θεσβ(ε)ίτης. Las traducciones modernas — español ''el tisbita'', francés ''le Tishbite'' — mantienen la forma transliterada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145906, 'spa', 'Tejido ornamental', 'Designa labor textil a cuadros, bordada o trenzada, específicamente un patrón decorativo sobre tela. Éxodo 28:4 prescribe una «túnica de labor a cuadros» (כְּתֹנֶת תַּשְׁבֵּץ) para el sumo sacerdote, indicando una técnica de tejido ornamental más elaborada que la tela común. El método exacto —cuadros tejidos, bordado o trenzado— sigue siendo incierto, pero el término denota claramente un acabado decorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145907, 'spa', 'Retorno estacional', 'Sentido temporal: retorno o punto de inflexión que marca el giro cíclico del año. La fórmula liteshuvat hashshanah (''al retorno del año'') señala la primavera, cuando los caminos se secaban y los ejércitos marchaban. En 1 Samuel 7:17 describe el circuito de Samuel regresando a Ramá. El árabe rujūʿ (''retorno'') refleja este significado direccional-temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145908, 'spa', 'Respuesta o réplica', 'Sentido discursivo: respuesta o réplica en una conversación o disputa. En Job 21:34 Job desestima los consuelos de sus amigos — ''vuestras respuestas no son sino falsedad''. En 34:36 Elihú sostiene que Job debe ser examinado por el carácter de sus ''respuestas'' (teshuvot). El tránsito de ''retorno'' espacial a ''respuesta'' verbal refleja una metáfora conceptual universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145914, 'spa', 'Depósito en custodia', 'Se refiere a una prenda, depósito o bien confiado a otra persona para su custodia, creando una responsabilidad fiduciaria. Levítico 6:2 aborda el caso de quien engaña respecto de «un depósito» (בִּתְשׂוּמֶת יָד), literalmente «en depósito de mano», algo puesto bajo su custodia. El término es paralelo a פִּקָּדוֹן, y ambos designan bienes confiados cuya violación acarrea restitución y ofrenda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145915, 'spa', 'Salvación o liberación en el sentido teológico amplio — los actos rescatadores d', 'Salvación o liberación en el sentido teológico amplio — los actos rescatadores de Dios, ya sea de opresión, peligro o peligro espiritual. Es el uso predominante (27 de 34 apariciones), abarcando la historia de Israel desde los jueces hasta los profetas. El salmista declara la fidelidad y el auxilio salvador de Dios en la gran asamblea (Sal 40:10-11), e Isaías habla de la salvación de Dios que se acerca (Is 46:13). El español ''salvación'' y el francés ''salut'' captan el peso teológico completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145918, 'spa', 'Victoria o triunfo, especialmente en contextos militares, que designa el desenla', 'Victoria o triunfo, especialmente en contextos militares, que designa el desenlace exitoso de una batalla atribuido a la intervención divina. El día de la liberación de Saúl en Jabes se convierte en ''día de victoria'' (1 S 11:9); las hazañas de Joab y Abisai en el campo de batalla producen teshuah (2 S 23:10, 12); y el triunfo de Naamán se llama teshuah para Aram (2 R 5:1). El español distingue entre ''salvación'' (teológico) y ''victoria'' (militar), revelando cómo la palabra tiende un puente entre ambos registros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145933, 'spa', 'deseo, anhelo', 'Las glosas translingüísticas enfatizan consistentemente el deseo—español ''deseo'', francés ''désir'', alemán ''Verlangen''. Las tres ocurrencias bíblicas abarcan un arco teológico notable: maldición (Gén 3:16), amenaza del pecado (Gén 4:7), y amor redimido (Cant 7:10). Las glosas francesas incluso usan formas infinitivas ''désirer'' (desear), enfatizando la fuerza verbal dentro del sustantivo. La evidencia multilingüe apoya esto como un concepto unitario de atracción intensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145934, 'spa', 'Regalo u ofrenda', 'Designa un regalo o presente, probablemente referido a la ofrenda acostumbrada que se llevaba al consultar a un profeta o varón santo. En 1 Samuel 9:7, Saúl y su criado se preocupan porque no tienen תְּשׁוּרָה que llevar a Samuel, lo que sugiere que tales obsequios eran protocolo esperado. La etimología es incierta, pero el contexto implica «cosa traída u ofrecida».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145935, 'spa', 'El noveno — ordinal que marca posición en secuencias calendáricas, ceremoniales ', 'El noveno — ordinal que marca posición en secuencias calendáricas, ceremoniales y administrativas. Se aplica al noveno mes (el mes de Kislev, 2 R 25:1; Jer 36:9), al noveno día, a la ofrenda del noveno líder tribal (Nm 7:60) y a la novena división de turnos sacerdotales o militares (1 Cr 12:12; 24:11; 25:16; 27:12). Aparece con el artículo (הַתְּשִׁיעִי) tanto para referentes masculinos como femeninos, siguiendo el uso ordinal estándar del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145938, 'spa', 'Nueve (cardinal) — El numeral cardinal ''nueve,'' atestiguado 54 veces en genealog', 'Nueve (cardinal) — El numeral cardinal ''nueve,'' atestiguado 54 veces en genealogías (Gn 5:5, 5:8, 5:11), censos y números compuestos. Las traducciones lo vierten uniformemente como ''nueve/nine/neuf/neun,'' sin ambigüedad semántica. Aparece tanto en construcciones independientes como compuestas (969 años en Gn 5:27, diecinueve en diversos recuentos), siempre con un valor numérico directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145941, 'spa', 'Noveno (ordinal/temporal) — Un uso ordinal-temporal (4 veces) donde בְּתִשְׁעָה ', 'Noveno (ordinal/temporal) — Un uso ordinal-temporal (4 veces) donde בְּתִשְׁעָה significa ''en el noveno (día/mes)'' en fórmulas calendáricas. Lv 23:32 fija el Día de la Expiación בְּתִשְׁעָה לַחֹדֶשׁ, y las fechas del asedio en 2 R 25:3, Jer 39:2 y Jer 52:6 marcan la brecha de las murallas de Jerusalén. Los traductores pasan a formas ordinales (''en el noveno día''), confirmando el desplazamiento funcional de cardinal a ordinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145950, 'spa', 'Noventa — el número cardinal noventa (90), usado en el AT en el cálculo de edade', 'Noventa — el número cardinal noventa (90), usado en el AT en el cálculo de edades patriarcales (Gn 5:9, 17, 30; 17:1, 17), totales censales y especificaciones de medidas. Frecuentemente se combina con unidades menores en enumeraciones como inventarios del templo y listas de retornados del exilio. Todas las principales tradiciones de traducción lo expresan con el equivalente numérico estándar: «noventa» en español, «quatre-vingt-dix» en francés, «neunzig» en alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (145952, 'spa', 'Prefecto persa', 'Identifica a un administrador persa específico que desempeña un papel clave en el relato de Esdras. A diferencia de las figuras hostiles de Esdras 4, Tatnai conduce una investigación legítima y, al descubrir el decreto original de Ciro en los archivos de Ecbatana, facilita la conclusión del templo. Su correspondencia ejemplifica el procedimiento burocrático del imperio persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146136, 'spa', 'el Espíritu Santo', 'Uso como componente del título divino πνεῦμα ἅγιον («Espíritu Santo»), la designación más frecuente del Espíritu de Dios en el Nuevo Testamento. Prácticamente cada pasaje de los Evangelios y Hechos sobre el Espíritu emplea esta construcción (Mt 1:18; 3:11; 28:19; Hch 1:8). Su traducción es notablemente uniforme: Espíritu Santo en español, Saint-Esprit en francés, Heiliger Geist en alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146137, 'spa', 'el Santo (título mesiánico)', 'Uso sustantivo singular como título cristológico: «el Santo de Dios» o «el Santo», aplicado a Jesús como designación mesiánica que resalta su consagración y pureza únicas. Pedro confiesa a Jesús como «el Santo de Dios» (Jn 6:69) y en Hechos el título reaparece en el discurso kerigmático (Hch 3:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146138, 'spa', 'hermano (biológico)', 'Hermano de sangre, varón nacido de la misma madre. Aparece en contextos donde el parentesco carnal es explícito: Santiago y Juan como hermanos (Mt 4:21), los «hermanos» de Jesús mencionados en Mt 13:55 y Mc 6:3, y las instrucciones sobre reconciliación con un hermano literal (Mt 5:23-24). Sentido minoritario pero fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146139, 'spa', 'hermano (correligionario)', 'Un miembro de la comunidad creyente tratado con cercanía familiar — el sentido abrumadoramente mayoritario en el NT. Pablo lo emplea constantemente para dirigirse a las congregaciones (Ro 1:13; 1 Co 1:10). No designa parentesco biológico, sino el vínculo espiritual de quienes comparten la fe en Cristo, transformando el vocabulario familiar en identidad eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146140, 'spa', 'ser humano, persona', 'Un ser humano individual, ya sea nombrado o indefinido, distinto de Dios, ángeles o animales. Este es el uso principal que cubre personas específicas (Mt 9:9, la vocación de Mateo), personas indefinidas en parábolas y enseñanzas (Mt 7:9, «¿qué hombre de vosotros?»), y referencias singulares genéricas. El español ''hombre'' funciona como término primario para este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146141, 'spa', 'Hijo del Hombre', 'Título cristológico ὁ υἱὸς τοῦ ἀνθρώπου, «el Hijo del Hombre», la autodesignación más característica de Jesús en los Evangelios. Arraigado en Dn 7:13, combina la humanidad de Jesús con su autoridad escatológica. El español traduce invariablemente «Hijo del Hombre», conservando la estructura genitiva del original griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146142, 'spa', 'Pacto (acuerdo bilateral entre Dios y su pueblo)', 'Pacto (acuerdo bilateral entre Dios y su pueblo): Pacto solemne y vinculante entre Dios y su pueblo, que abarca el arco completo de la historia de la salvación: el pacto con Abraham (Hch 3:25; Gá 3:17), la antigua alianza mediada por Moisés (2 Co 3:14; He 8:9) y el nuevo pacto inaugurado en la Última Cena (Mt 26:28; Lc 22:20; 1 Co 11:25). El español «pacto», el francés «alliance» y el suajili «agano» transmiten la idea de un acuerdo solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146143, 'spa', 'Testamento, última voluntad (documento legal)', 'Testamento, última voluntad (documento legal): Testamento — documento legal de última voluntad. Este sentido jurídico del griego clásico aparece en Hebreos 9:16-17, donde el autor explota deliberadamente la doble acepción de διαθήκη para argumentar que la muerte de Cristo fue necesaria para activar el nuevo pacto, del mismo modo que un testamento solo cobra vigencia con la muerte del testador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146144, 'spa', 'rectitud moral, integridad etica', 'La dimensión etica de la justicia: conducta recta conforme a la norma de Dios. En el Sermon del Monte designa la vida integra que Dios requiere y recompensa (Mt 5:6, 10, 20; 6:1). Se trata de la rectitud practica del creyente que vive en obediencia a los mandamientos divinos y busca la conformidad moral con su voluntad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146145, 'spa', 'justificacion forense, posicion ante Dios', 'El sentido juridico-teologico: la declaracion de Dios por la cual el pecador es tenido por justo mediante la fe en Cristo. Central en la teologia paulina (Ro 3:21-22; Fil 3:9), esta justicia no proviene de las obras de la ley sino que se recibe como don gratuito, constituyendo la base de la reconciliacion del creyente con Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146146, 'spa', 'fidelidad al pacto, accion salvifica', 'La justicia como atributo activo de Dios: su fidelidad al pacto y su intervencion salvifica en favor de su pueblo. Cuando Pablo habla de ''la justicia de Dios'' (Ro 1:17; 3:5), no se refiere solo a un atributo estatico sino a la accion dinamica por la cual Dios cumple sus promesas y vindica a los suyos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146147, 'spa', 'temporal', 'Referencia a tiempo o momento, ''ser'' en sentido temporal, como en ''es la hora'', ''era el día''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146149, 'spa', 'iglesia local, congregación', 'Una congregación cristiana local reunida en un lugar específico — una iglesia doméstica o comunidad urbana. Pablo escribe ''a la iglesia de Dios que está en Corinto'' (1 Co 1:2), saluda ''a la iglesia que se reúne en su casa'' (Ro 16:5; Flm 1:2), y se refiere a ''las iglesias de Galacia'' (Gá 1:2). Este sentido de comunidad local y visible es el más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146150, 'spa', 'iglesia universal, cuerpo de Cristo', 'La iglesia como realidad cósmica y universal, el cuerpo de Cristo que trasciende toda congregación local. Pablo declara que Cristo es ''cabeza sobre todas las cosas a la iglesia, la cual es su cuerpo'' (Ef 1:22-23), y que Cristo ''amó a la iglesia y se entregó a sí mismo por ella'' (Ef 5:25). Este sentido eclesiológico elevado predomina en Efesios y Colosenses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146151, 'spa', 'por encima de/autoridad', 'Posición de poder, dominio o autoridad sobre personas o cosas; gobernando sobre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146153, 'spa', 'vida biológica, vitalidad', 'La existencia física y corporal, el hecho de estar vivo en sentido natural. Aunque minoritario en el NT frente al sentido teológico, aparece cuando se habla de la vida terrena como tal — la duración de la existencia humana, el sustento cotidiano o la vitalidad del cuerpo. En contextos donde no hay carga teológica explícita, ζωή designa simplemente el estar con vida en contraste con la muerte física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146154, 'spa', 'vida eterna, vida divina', 'La vida como realidad divina y eterna, don de Dios a través de Cristo. Este es el sentido dominante en el NT, especialmente en los escritos joánicos: «en él estaba la vida, y la vida era la luz de los hombres» (Jn 1:4); «esta es la vida eterna: que te conozcan a ti» (Jn 17:3). Pablo la opone a la muerte como consecuencia del pecado (Ro 6:23). Abarca la participación presente del creyente en la vida de Dios y su consumación futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146155, 'spa', 'fruto o producto agrícola', 'Fruto o producto en sentido literal agrícola: el rendimiento de árboles, viñas y campos. Incluye la higuera sin fruto (Mt 21:19), la cosecha esperada (Mr 12:2), el labrador que aguarda el fruto de la tierra (Stg 5:7) y el árbol de la vida con doce frutos (Ap 22:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146156, 'spa', 'fruto espiritual o moral', 'Uso metafórico de fruto como resultado o producto moral y espiritual de la vida de una persona. Juan el Bautista exige ''fruto digno de arrepentimiento'' (Mt 3:8), Jesús enseña que el árbol se conoce por su fruto (Mt 7:16-20), y Pablo enumera el ''fruto del Espíritu'' (Gá 5:22). Es la metáfora ética central del NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146157, 'spa', 'cabeza (parte del cuerpo)', 'La cabeza como parte anatómica del cuerpo humano o animal. Incluye la cabeza sobre la que no se puede alterar el color de un cabello (Mt 5:36), la cabeza ungida con aceite (Mt 6:17), la cabeza cortada de Juan el Bautista (Mt 14:8) y la cabeza de Cristo coronada de espinas. Es el sentido físico literal sin carga metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146158, 'spa', 'cabeza (autoridad, preeminencia)', 'Uso metafórico de cabeza como símbolo de autoridad, preeminencia o fuente de origen. Pablo lo desarrolla como término teológico central: Cristo como ''cabeza'' de la iglesia (Ef 1:22; Col 1:18), el marido como ''cabeza'' de la mujer (1 Co 11:3), y Cristo como cabeza de todo principado y potestad (Col 2:10). Conlleva subordinación relacional más que mera superioridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146159, 'spa', 'mundo como creación amada', 'El mundo como creación de Dios y objeto de su amor redentor: el ámbito al que el Hijo es enviado para salvar. «De tal manera amó Dios al mundo» (Jn 3:16) es la expresión paradigmática. Aquí κόσμος no designa un sistema hostil sino la humanidad necesitada de gracia. El español mundo y el francés monde captan este sentido positivo universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146160, 'spa', 'mundo opuesto a Dios', 'El mundo como sistema de valores, deseos y poderes humanos organizados en oposición a Dios y su reino. En la teología joánica, este κόσμος «no conoció» a Cristo (Jn 1:10), «yace en el maligno» (1 Jn 5:19) y genera un «amor al mundo» incompatible con el amor del Padre (1 Jn 2:15-16). El español mundo abarca este matiz negativo cuando el contexto lo señala.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146161, 'spa', 'piedra, roca (literal)', 'Piedra o roca como objeto físico concreto: rocas naturales (Mt 3:9; 4:3), sillares del templo (Mr 13:1-2), la piedra que selló el sepulcro (Mt 27:60; 28:2), piedras preciosas (Ap 21:19) y piedras arrojadas como arma en lapidaciones (Jn 8:59; Hch 7:58-59). El uso literal predomina en los evangelios y en el Apocalipsis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146162, 'spa', 'piedra (metáfora cristológica)', 'Uso figurado cristológico: Cristo como la piedra que desecharon los edificadores y vino a ser cabeza del ángulo (Mt 21:42; 1 P 2:7), piedra de tropiezo y roca de escándalo (Ro 9:33; 1 P 2:8), y piedra viva sobre la cual los creyentes son edificados como casa espiritual (1 P 2:4-5). Esta metáfora vertebra la eclesiología neotestamentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146163, 'spa', 'camino físico, ruta', 'Un camino, ruta o senda en sentido literal y físico. Incluye la ruta a Egipto (Mt 2:12), ''el camino del mar'' (Mt 4:15) y el sendero donde cae la semilla del sembrador (Mt 13:4). El español camino cubre tanto senderos rurales como rutas principales, sin necesidad de marcadores adicionales para distinguir escala.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146164, 'spa', 'modo de vida, conducta', 'Camino en sentido figurado de curso de vida, conducta o dirección espiritual. Juan el Bautista prepara ''el camino del Señor'' (Mt 3:3), Jesús es ''el camino, la verdad y la vida'' (Jn 14:6), y los caminos ancho y estrecho definen dos destinos últimos (Mt 7:13-14). Español camino extiende naturalmente su uso literal al metafórico, como ocurre en la mayoría de las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146165, 'spa', 'Ira divina (furia judicial asentada)', 'Ira divina (furia judicial asentada). La indignación soberana de Dios contra el pecado, expresada como juicio definitivo. Juan el Bautista advierte sobre «la ira venidera» (Mt 3:7), Pablo enseña que la ira de Dios se revela contra toda impiedad (Ro 1:18) y que los creyentes son salvos de la ira por medio de Cristo (Ro 5:9), y Apocalipsis describe «el gran día de su ira» (Ap 6:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146166, 'spa', 'Ira humana (respuesta emocional apasionada)', 'Ira humana (respuesta emocional apasionada). El enojo intenso como reacción pasional del ser humano. Marcos 3:5 ofrece el ejemplo clave, donde Jesús mira a su alrededor «con enojo,» afligido por la dureza de sus corazones. Se distingue de la ira divina por ser una emoción circunstancial y transitoria más que un juicio soberano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146167, 'spa', 'cielo, firmamento, atmósfera', 'La bóveda visible sobre la tierra: el espacio donde vuelan las aves (Mt 6:26), donde aparecen señales meteorológicas (Mt 16:2-3) y donde brillan los astros. Es el sentido físico y observable de οὐρανός, el firmamento creado que un día pasará (Mt 5:18; 24:29). El español «cielo» cubre este sentido sin ambigüedad cuando el contexto lo acompaña.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146168, 'spa', 'cielo (morada divina)', 'La morada trascendente de Dios, el ámbito celestial donde residen la autoridad divina y la recompensa eterna. Jesús lo invoca como el lugar del Padre (Mt 6:20) y origen de su propia autoridad. El plural «cielos» intensifica esta dimensión sobrenatural, especialmente en la fórmula mateana «reino de los cielos». Las traducciones hispanas oscilan entre «cielo» y «cielos» según el registro litúrgico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146169, 'spa', 'padre biológico o adoptivo', 'Un padre humano en sentido biológico o adoptivo: el progenitor varón en genealogías, relatos familiares y enseñanzas sobre la relación paterno-filial. Incluye a José como padre de Jesús (Lc 2:48), padres en las parábolas (Mt 21:31) y referencias genéricas a la autoridad paterna (Ef 6:4). El español padre cubre este sentido sin ambigüedad cuando el contexto es humano y familiar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146170, 'spa', 'Dios como Padre', 'Título divino que designa a Dios como Padre en relación con Jesucristo y con los creyentes. Jesús se dirige a Dios como «Padre» (Mt 6:9; Jn 17:1), y la teología relacional Padre-Hijo de Pablo y Juan se articula en torno a este término. Es el sentido teológicamente más denso, dominante en el Evangelio de Juan y las epístolas, donde «Padre» es a la vez nombre propio y confesión trinitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146171, 'spa', 'Beber (consumir líquido)', 'Sentido literal: beber o consumir un líquido en contextos cotidianos y festivos. Incluye beber agua, vino u otras bebidas (Mt 6:25; 11:18-19; Lc 7:33-34; Jn 2:10), dar de beber al sediento (Mt 25:35) y las referencias al comer y beber como actividades ordinarias de la vida diaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146172, 'spa', 'Beber (sufrimiento, sustento espiritual)', 'Sentido figurado: participar del sufrimiento de Cristo (Mt 20:22; Mr 10:38 — ''beber la copa''), recibir sustento espiritual (1 Co 10:4; Jn 7:37) y compartir en el pacto eucarístico (Mt 26:27-29; 1 Co 11:25). La imagen de beber trasciende lo físico para expresar comunión profunda con la obra redentora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146173, 'spa', 'barca de pesca', 'Barca pequeña o embarcación de pesca empleada en aguas interiores, principalmente el mar de Galilea. Los Evangelios sinópticos y Juan usan πλοῖον para la embarcación de trabajo de los discípulos: las barcas desde las que pescan (Lc 5:2-3), en las que Jesús sube para enseñar (Mc 4:1), y que son sacudidas por las tormentas (Mat 8:23-24; Mc 4:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146174, 'spa', 'barco de navegación', 'Navío de navegación marítima, sentido duplicado que confirma la distinción entre la embarcación de aguas interiores y el barco de alta mar. Cubre los mismos contextos de travesías paulinas y comercio marítimo que el sentido 2, reforzando la frontera semántica entre barca y navío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146175, 'spa', 'Espíritu Santo (persona divina)', 'El Espíritu Santo, el Espíritu de Dios o de Cristo — el sentido masivamente dominante con 370 de 383 apariciones. Cubre el papel del Espíritu en la concepción de Jesús (Mt 1:18, 20), la capacitación de los creyentes en Pentecostés (Hch 2:4), la presencia que mora en ellos y produce fruto (Gá 5:22) y el agente de revelación profética (2 P 1:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146176, 'spa', 'espíritu humano (antropológico)', 'El espíritu humano, la vida interior inmaterial, la disposición o sede de la voluntad y la conciencia moral. Aparece donde πνεῦμα se refiere a lo distintivamente humano más que a lo divino — Lucas 1:80 (''el niño crecía y se fortalecía en espíritu''), 1 Corintios 14:2 (''en su espíritu'') y el ambiguo 1 Pedro 3:18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146177, 'spa', 'ser espiritual (angélico/demoníaco)', 'Un ser espiritual o entidad sobrenatural — ángel, demonio o espíritu inmundo que actúa como agente incorpóreo. Las apariciones se concentran en la discusión paulina de los dones espirituales (1 Co 12:10, ''discernimiento de espíritus'') y las visiones simbólicas de Apocalipsis (Ap 1:4; 4:5, ''los siete espíritus ante su trono'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146178, 'spa', 'viento, soplo (físico)', 'Categoría combinada para los usos físicos de πνεῦμα — tanto el viento de Juan 3:8 como el soplo de 2 Tesalonicenses 2:8 — donde la palabra retorna a su sentido etimológico de aire en movimiento. El español distingue ''viento'' (fenómeno meteorológico) de ''soplo'' (exhalación), ambos claramente separados del vocabulario espiritual o teológico.');